<script setup lang="ts">
import { computed } from 'vue';
import type { WorkerRequest } from '../../application/request-gates';
import { acceptedExecutionProfile, deliveryAssessments } from '../delivery-provider-view';
import { date } from '../store';
import MessageContent from './MessageContent.vue';
const props = defineProps<{ subject: WorkerRequest }>();
const accepted = computed(() => acceptedExecutionProfile(props.subject));
const assessments = computed(() => deliveryAssessments(props.subject));
</script>
<template>
  <details v-if="accepted || assessments.length || subject.delivery?.handoffs?.length" class="delivery-detail"><summary>Providers, review and continuation</summary>
    <template v-if="accepted"><h3>Accepted execution profile · {{ accepted.resolution.profile.id }}</h3><p>{{ accepted.resolution.source === 'rule' ? 'Selected by routing rule ' + accepted.resolution.ruleId : accepted.resolution.source === 'override' ? 'Explicit project-authorized request override' : 'Project default profile' }}. This selection was frozen at admission.</p><dl><div><dt>Provider and model</dt><dd>{{ accepted.selection.provider }} · {{ accepted.selection.model || 'Provider default' }}</dd></div><div><dt>Authentication</dt><dd>{{ accepted.resolution.profile.authenticationMode === 'api-key' ? 'API key · provider billing' : 'CLI account · provider plan' }}</dd></div><div><dt>Effort</dt><dd>{{ accepted.selection.effort || 'Provider default' }}</dd></div><div><dt>Tool permission boundary</dt><dd>{{ accepted.resolution.profile.boundary === 'provider_native' ? 'Provider-native permissions and hooks' : 'Worker tool grants' }}</dd></div><div><dt>Candidate review profile</dt><dd>{{ accepted.policy.reviewProfile || 'No separate model reviewer' }}</dd></div><div><dt>Fallback allowance</dt><dd>{{ accepted.policy.maxHandoffs }} handoffs · {{ accepted.policy.fallbackProfiles.join(', ') || 'No fallback profiles' }}</dd></div></dl><p v-if="accepted.resolution.profile.boundary === 'provider_native'" class="caption">This adapter uses its own permission controls. Werk does not claim per-tool enforcement inside the provider CLI; reviewer access must be permitted there too.</p></template>
    <article v-for="item in assessments" :key="item.assessment.stepId" class="entry"><h3>{{ item.current ? 'Current candidate model assessment' : 'Retained model assessment · historical candidate' }}</h3><p>{{ item.assessment.profileId }} · {{ item.assessment.selection.provider }} · {{ date(item.assessment.at) }}</p><p class="caption">{{ item.assessment.passed ? 'No blocking model findings were recorded.' : 'Blocking model findings were recorded.' }} This is advisory evidence; it does not substitute for commands, criterion results or human acceptance.</p><MessageContent :text="item.assessment.summary" /><ul><li v-for="finding in item.assessment.findings" :key="finding.id"><strong>{{ finding.severity }}</strong> · {{ finding.message }}</li></ul><details><summary>Assessment subject</summary><p>Candidate <code>{{ item.assessment.candidate.candidateCommit }}</code></p><p>Invocation <code>{{ item.assessment.invocationRunId }}</code> · step <code>{{ item.assessment.stepId }}</code></p></details></article>
    <article v-for="handoff in subject.delivery?.handoffs ?? []" :key="handoff.id" class="entry"><h3>{{ handoff.sourceProfileId }} → {{ handoff.targetProfileId }}</h3><p>{{ handoff.reason.replaceAll('_', ' ') }} · {{ date(handoff.at) }}</p><p class="caption">Continuation used a fresh provider session with the retained candidate and project context. A native conversation handle was not transferred.</p><MessageContent :text="handoff.summary" /><dl><div><dt>Checkpoint commit</dt><dd>{{ handoff.checkpointCommit || 'No commit recorded' }}</dd></div><div><dt>Source invocation</dt><dd>{{ handoff.sourceInvocationRunId }}</dd></div><div><dt>Target invocation</dt><dd>{{ handoff.targetInvocationRunId }}</dd></div><div><dt>Accepted input revision</dt><dd>{{ handoff.inputRevision }}</dd></div></dl></article>
  </details>
</template>
<style scoped src="./delivery-detail.css"></style>
